    updated_at TEXT NOT NULL
  , system_message TEXT DEFAULT NULL, tool_filter_regex TEXT DEFAULT NULL, context_cache_protection INTEGER DEFAULT 0, tenant_id TEXT NOT NULL DEFAULT 'red');
CREATE TABLE api_keys (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    key TEXT NOT NULL UNIQUE,
    machine_id TEXT,
    allowed_models TEXT DEFAULT '[]',
    no_log INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
  , revoked_at TEXT, expires_at TEXT, last_used_at TEXT, key_prefix TEXT, ip_allowlist TEXT, scopes TEXT, allowed_combos TEXT, throttle_delay_ms INTEGER, stream_default_mode TEXT NOT NULL DEFAULT 'legacy', allowed_quotas TEXT NOT NULL DEFAULT '[]', disable_non_public_models INTEGER NOT NULL DEFAULT 0, usage_limit_enabled INTEGER NOT NULL DEFAULT 0, daily_usage_limit_usd REAL, weekly_usage_limit_usd REAL, cache_default_mode TEXT NOT NULL DEFAULT 'legacy', model_access_mode TEXT NOT NULL DEFAULT 'all'
CHECK (model_access_mode IN ('all', 'restricted')), compression_enabled INTEGER NOT NULL DEFAULT 1, tenant_id TEXT NOT NULL DEFAULT 'red', blocked_models TEXT, allowed_connections TEXT, auto_resolve INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1, access_schedule TEXT, max_requests_per_day INTEGER, max_requests_per_minute INTEGER, max_sessions INTEGER NOT NULL DEFAULT 0, rate_limits TEXT, is_banned INTEGER NOT NULL DEFAULT 0, key_hash TEXT, proxy_id TEXT, allowed_endpoints TEXT, allow_usage_command INTEGER NOT NULL DEFAULT 0, chaos_mode_enabled INTEGER NOT NULL DEFAULT 0, allow_auto_combos INTEGER NOT NULL DEFAULT 1, catalog_scope TEXT NOT NULL DEFAULT 'all' CHECK (catalog_scope IN ('all', 'combos', 'models')));
CREATE TABLE db_meta (
