  , video_content_removed INTEGER NOT NULL DEFAULT 0, ttft_ms INTEGER DEFAULT NULL, model_pinned INTEGER DEFAULT 0, session_tag TEXT DEFAULT NULL, reasoning_duration_ms INTEGER DEFAULT NULL, reasoning_effort_requested TEXT DEFAULT NULL, reasoning_effort_upstream TEXT DEFAULT NULL, reasoning_encrypted INTEGER DEFAULT NULL, has_content INTEGER DEFAULT NULL, usage_provenance TEXT DEFAULT NULL, resilience_actions TEXT DEFAULT NULL, end_user TEXT DEFAULT NULL, tags TEXT DEFAULT NULL, reasoning_source TEXT DEFAULT NULL, reasoning_chars INTEGER DEFAULT NULL, response_id TEXT DEFAULT NULL, error_type TEXT DEFAULT NULL);
