CREATE TRIGGER trg_free_proxies_clear_pool_proxy_id
AFTER DELETE ON proxy_registry
FOR EACH ROW
BEGIN
  UPDATE free_proxies
  SET pool_proxy_id = NULL,
      in_pool = 0,
      updated_at = datetime('now')
  WHERE pool_proxy_id = OLD.id;
END;
