CREATE TABLE server_tool_executions (
  id TEXT PRIMARY KEY,
  api_key_id TEXT NOT NULL,
  request_identity TEXT NOT NULL,
  tool_call_id TEXT NOT NULL,
  tool_name TEXT NOT NULL,
  input_digest TEXT NOT NULL,
  output TEXT,
  status TEXT NOT NULL CHECK(status IN ('running', 'success', 'error', 'timeout')),
  error_message TEXT,
  duration_ms INTEGER,
  claim_expires_at TEXT NOT NULL,
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(api_key_id, request_identity, tool_call_id)
);
CREATE INDEX idx_server_tool_executions_status_expiry
  ON server_tool_executions(status, claim_expires_at);
CREATE INDEX idx_server_tool_executions_created
  ON server_tool_executions(created_at);
CREATE TABLE xp_action_counts (
  api_key_id TEXT NOT NULL,
  action TEXT NOT NULL,
  count INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (api_key_id, action)
) WITHOUT ROWID;
CREATE TABLE request_cost_ledger (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  api_key_id        TEXT NOT NULL,
  provider          TEXT NOT NULL,
  model             TEXT NOT NULL,
  tokens_input      INTEGER NOT NULL DEFAULT 0,
  tokens_output     INTEGER NOT NULL DEFAULT 0,
  tokens_cache_read INTEGER NOT NULL DEFAULT 0,
  tokens_cache_creation INTEGER NOT NULL DEFAULT 0,
  tokens_reasoning  INTEGER NOT NULL DEFAULT 0,
  unit_price_input  REAL NOT NULL DEFAULT 0,
  unit_price_output REAL NOT NULL DEFAULT 0,
  amount_usd        REAL NOT NULL DEFAULT 0,
  service_tier      TEXT NOT NULL DEFAULT 'standard',
  success           INTEGER NOT NULL DEFAULT 1,
  timestamp         TEXT NOT NULL,
  request_id        TEXT
, end_user TEXT, tags TEXT, session_id TEXT, tenant_id TEXT, event_id TEXT, usage_attributes TEXT NOT NULL DEFAULT '{}', pricing_known INTEGER NOT NULL DEFAULT 1, pricing_snapshot TEXT);
CREATE INDEX idx_rcl_api_key_timestamp ON request_cost_ledger(api_key_id, timestamp);
CREATE INDEX idx_rcl_timestamp ON request_cost_ledger(timestamp);
CREATE TABLE api_key_quota_limits (
  api_key_id         TEXT PRIMARY KEY,
  tpm_limit          INTEGER,
  rpm_limit          INTEGER,
  monthly_amount_usd REAL,
  updated_at         TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE api_key_quota_counters (
  api_key_id    TEXT NOT NULL,
  dimension_key TEXT NOT NULL,
  bucket_index  INTEGER NOT NULL,
  consumed      REAL NOT NULL DEFAULT 0,
  updated_at    INTEGER NOT NULL,
  PRIMARY KEY (api_key_id, dimension_key, bucket_index)
);
CREATE INDEX idx_akqc_dim_bucket ON api_key_quota_counters(dimension_key, bucket_index);
CREATE INDEX idx_akqc_updated_at ON api_key_quota_counters(updated_at);
CREATE INDEX idx_turn_nodes_last_seen
  ON conversation_turn_nodes(last_seen_at);
CREATE TABLE quota_schedules (
  id             TEXT    PRIMARY KEY,
  pool_id        TEXT    NOT NULL,
  label          TEXT,
  days           TEXT    NOT NULL,
  start_minute   INTEGER NOT NULL CHECK (start_minute >= 0 AND start_minute < 1440),
  end_minute     INTEGER NOT NULL CHECK (end_minute > 0 AND end_minute <= 1440),
  timezone       TEXT,
  mode           TEXT    NOT NULL DEFAULT 'allow' CHECK (mode IN ('allow','block')),
  reserves       TEXT,
  budget_value   REAL             CHECK (budget_value IS NULL OR budget_value > 0),
  budget_unit    TEXT             CHECK (budget_unit IS NULL OR budget_unit IN ('requests','tokens','usd')),
  budget_window  TEXT    NOT NULL DEFAULT 'daily' CHECK (budget_window IN ('hourly','5h','daily','weekly','monthly')),
  priority       INTEGER NOT NULL DEFAULT 0,
  enabled        INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)),
  created_at     TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_quota_schedules_pool
  ON quota_schedules(pool_id, enabled);
CREATE TABLE video_jobs (
  id TEXT PRIMARY KEY,
  owner_hash TEXT NOT NULL,
  idempotency_hash TEXT,
  request_hash TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('generations', 'edits', 'extensions')),
  provider TEXT NOT NULL,
  model TEXT NOT NULL,
  connection_id TEXT NOT NULL,
  upstream_request_id TEXT,
  state TEXT NOT NULL CHECK (state IN ('reserved', 'submitted', 'uncertain', 'failed')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (owner_hash, idempotency_hash)
);
CREATE INDEX idx_video_jobs_owner_created
  ON video_jobs(owner_hash, created_at DESC);
CREATE INDEX idx_video_jobs_owner_upstream
  ON video_jobs(owner_hash, upstream_request_id);
CREATE TABLE api_key_daily_token_limits (
  api_key_id         TEXT PRIMARY KEY,
  daily_tokens_limit INTEGER NOT NULL CHECK (daily_tokens_limit > 0),
  updated_at         TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE redrouter_usage_sinks (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  url TEXT NOT NULL,
  secret_encrypted TEXT NOT NULL,
  mode TEXT NOT NULL CHECK (mode IN ('instant', 'window')),
  window_sec INTEGER,
  api_key_ids TEXT,
  enabled INTEGER NOT NULL DEFAULT 0,
  cursor_id INTEGER NOT NULL DEFAULT 0,
  next_window_end TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, type TEXT NOT NULL DEFAULT 'webhook', config TEXT);
CREATE TABLE redrouter_usage_deliveries (
  id TEXT PRIMARY KEY,
  sink_id TEXT NOT NULL REFERENCES redrouter_usage_sinks(id) ON DELETE CASCADE,
  payload TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'sending', 'delivered', 'dead')),
  attempts INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TEXT,
  lease_until TEXT,
  last_status INTEGER,
  last_error TEXT,
  delivered_at TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_redrouter_usage_delivery_due
  ON redrouter_usage_deliveries(status, next_attempt_at);
CREATE INDEX idx_redrouter_usage_delivery_sink
  ON redrouter_usage_deliveries(sink_id, created_at);
CREATE TABLE redrouter_usage_windows (
  sink_id TEXT PRIMARY KEY REFERENCES redrouter_usage_sinks(id) ON DELETE CASCADE,
  target_id INTEGER NOT NULL,
  start_at TEXT NOT NULL,
  end_at TEXT NOT NULL,
  next_window_end TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE "api_key_token_limits" (
  id              TEXT PRIMARY KEY,
  api_key_id      TEXT NOT NULL,
  scope_type      TEXT NOT NULL CHECK (scope_type IN ('model', 'provider', 'global')),
  scope_value     TEXT NOT NULL DEFAULT '',
  token_limit     INTEGER NOT NULL CHECK (token_limit > 0),
  reset_interval  TEXT NOT NULL DEFAULT 'monthly' CHECK (reset_interval IN ('daily', 'weekly', 'monthly')),
  reset_time      TEXT,
  enabled         INTEGER NOT NULL DEFAULT 1,
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (api_key_id, scope_type, scope_value, reset_interval)
);
CREATE INDEX idx_aktl_api_key_id ON api_key_token_limits (api_key_id);
CREATE TABLE redrouter_cache_prefix_observations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  timestamp TEXT NOT NULL,
  conversation_key TEXT NOT NULL,
  provider TEXT,
  model TEXT,
  connection_id TEXT,
  api_key_id TEXT,
  request_index INTEGER NOT NULL,
  message_count INTEGER NOT NULL,
  previous_message_count INTEGER NOT NULL,
  stable_prefix_messages INTEGER NOT NULL,
  first_divergent_index INTEGER NOT NULL,
  cause TEXT NOT NULL,
  causes TEXT NOT NULL
);
CREATE INDEX idx_rcpo_timestamp
  ON redrouter_cache_prefix_observations (timestamp);
CREATE INDEX idx_rcpo_conversation
  ON redrouter_cache_prefix_observations (conversation_key, id);
CREATE TABLE budgets (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  max_usd REAL NOT NULL CHECK (max_usd > 0),
  -- NULL means "80% of max_usd".
  soft_usd REAL,
  duration TEXT NOT NULL DEFAULT 'monthly'
    CHECK (duration IN ('daily', 'weekly', 'monthly', 'total')),
  -- HH:MM (UTC) the window rolls over, same meaning as the per-key budget's resetTime.
  reset_time TEXT,
  on_exceed TEXT NOT NULL DEFAULT 'block' CHECK (on_exceed IN ('block', 'throttle')),
  throttle_delay_ms INTEGER NOT NULL DEFAULT 1000,
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, tpm_limit INTEGER, rpm_limit INTEGER, model_max_json TEXT);
CREATE TABLE budget_windows (
  budget_id TEXT NOT NULL,
  scope_value TEXT NOT NULL,
  window_start INTEGER NOT NULL,
  spent_usd REAL NOT NULL DEFAULT 0,
  alerted_at TEXT,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (budget_id, scope_value, window_start),
  FOREIGN KEY (budget_id) REFERENCES budgets(id) ON DELETE CASCADE
);
CREATE TABLE guardrail_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  -- Epoch milliseconds.
  ts INTEGER NOT NULL,
  guardrail_id TEXT NOT NULL,
  stage TEXT NOT NULL CHECK (stage IN ('request', 'response')),
  action TEXT NOT NULL CHECK (action IN ('block', 'flag', 'mask')),
  api_key_id TEXT,
  request_id TEXT,
  -- Operator content-filter rule id, when a rule fired.
  rule_id TEXT
);
CREATE INDEX idx_guardrail_events_ts ON guardrail_events(ts);
CREATE INDEX idx_guardrail_events_guardrail_ts ON guardrail_events(guardrail_id, ts);
CREATE TABLE budget_window_models (
  budget_id TEXT NOT NULL,
  scope_value TEXT NOT NULL,
  window_start INTEGER NOT NULL,
  cap_key TEXT NOT NULL,
  spent_usd REAL NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (budget_id, scope_value, window_start, cap_key),
  FOREIGN KEY (budget_id) REFERENCES budgets(id) ON DELETE CASCADE
);
CREATE TABLE "budget_assignments" (
  budget_id TEXT NOT NULL,
  -- 'key' = api_keys.id, 'group' = key_groups.id (a team; the whole group shares one window),
  -- 'tag' = a lowercased request tag, 'user' = an end-user id as sent by the client.
  scope_type TEXT NOT NULL CHECK (scope_type IN ('key', 'group', 'tag', 'user')),
  scope_value TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE (scope_type, scope_value, budget_id),
  FOREIGN KEY (budget_id) REFERENCES budgets(id) ON DELETE CASCADE
);
CREATE INDEX idx_budget_assignments_budget ON budget_assignments (budget_id);
CREATE INDEX idx_rcl_end_user_timestamp ON request_cost_ledger (end_user, timestamp);
CREATE TABLE tenants (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  is_default INTEGER NOT NULL DEFAULT 0,
  disabled INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE tenant_users (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  email TEXT NOT NULL UNIQUE,
  display_name TEXT,
  role TEXT NOT NULL CHECK (role IN ('admin', 'user')),
  password_hash TEXT,
  disabled INTEGER NOT NULL DEFAULT 0,
  last_login_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, session_version INTEGER NOT NULL DEFAULT 0);
CREATE INDEX idx_tenant_users_tenant ON tenant_users(tenant_id);
CREATE TABLE tenant_shared_resources (
  kind TEXT NOT NULL CHECK (kind IN ('connection', 'combo')),
  resource_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (kind, resource_id)
);
CREATE INDEX idx_api_keys_tenant ON api_keys(tenant_id);
CREATE INDEX idx_provider_connections_tenant ON provider_connections(tenant_id);
CREATE INDEX idx_combos_tenant ON combos(tenant_id);
CREATE TABLE auth_mfa (
  principal TEXT PRIMARY KEY,
  secret_encrypted TEXT NOT NULL,
  recovery_hashes TEXT NOT NULL DEFAULT '[]',
  enabled INTEGER NOT NULL DEFAULT 0,
  last_used_step INTEGER,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE login_lockouts (
  key TEXT PRIMARY KEY,
  level INTEGER NOT NULL DEFAULT 0,
  locked_until INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);
CREATE TABLE tenant_invites (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  accepted_at TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_tenant_invites_user ON tenant_invites(user_id);
CREATE TABLE tenant_routing_policy (
  tenant_id TEXT PRIMARY KEY,
  owner_transparent INTEGER,
  owner_priority TEXT,
  tenant_transparent INTEGER,
  tenant_priority TEXT,
  updated_at TEXT NOT NULL
);
CREATE TABLE tenant_profiles (
  tenant_id TEXT PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,
  owner_user_id TEXT REFERENCES tenant_users(id) ON DELETE SET NULL,
  owner_email TEXT NOT NULL DEFAULT '',
  technical_email TEXT NOT NULL DEFAULT '',
  billing_email TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  metadata TEXT NOT NULL DEFAULT '{}',
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_uh_tenant_month ON usage_history(tenant_id, timestamp, api_key_id);
CREATE INDEX idx_rcl_tenant_month ON request_cost_ledger(tenant_id, timestamp, api_key_id);
CREATE UNIQUE INDEX idx_cost_ledger_event_id
  ON request_cost_ledger(event_id) WHERE event_id IS NOT NULL;
CREATE TABLE cost_ledger_outbox (
  event_id TEXT PRIMARY KEY,
  api_key_id TEXT NOT NULL,
  payload TEXT NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_cost_outbox_key ON cost_ledger_outbox(api_key_id);
CREATE TABLE budget_inflight (
  id TEXT PRIMARY KEY,
  api_key_id TEXT NOT NULL,
  usd REAL NOT NULL CHECK(usd >= 0),
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL
);
CREATE INDEX idx_budget_inflight_key ON budget_inflight(api_key_id, expires_at);
CREATE TABLE budget_inflight_scopes (
  reservation_id TEXT NOT NULL REFERENCES budget_inflight(id) ON DELETE CASCADE,
  budget_id TEXT NOT NULL,
  scope_value TEXT NOT NULL,
  window_start INTEGER NOT NULL,
  cap_key TEXT NOT NULL DEFAULT '',
  PRIMARY KEY(reservation_id, budget_id, scope_value, window_start, cap_key)
);
CREATE TABLE routing_profiles (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  transparent INTEGER CHECK (transparent IN (0, 1) OR transparent IS NULL),
  priority TEXT,
  updated_at TEXT NOT NULL
);
CREATE TABLE routing_profile_bindings (
  scope TEXT PRIMARY KEY,
  tenant_id TEXT REFERENCES tenants(id) ON DELETE CASCADE,
  profile_id TEXT NOT NULL REFERENCES routing_profiles(id) ON DELETE RESTRICT,
  transparent_override INTEGER CHECK (transparent_override IN (0, 1) OR transparent_override IS NULL),
  priority_override TEXT
);
CREATE INDEX idx_routing_profile_bindings_profile ON routing_profile_bindings(profile_id);
CREATE INDEX idx_routing_profile_bindings_tenant ON routing_profile_bindings(tenant_id);
CREATE TABLE api_key_usage_reservations (
  id TEXT PRIMARY KEY,
  api_key_id TEXT NOT NULL,
  reserved_tokens INTEGER NOT NULL CHECK (reserved_tokens >= 0),
  reserved_usd REAL NOT NULL CHECK (reserved_usd >= 0),
  created_at INTEGER NOT NULL CHECK (created_at >= 0),
  state TEXT NOT NULL CHECK (state IN ('reserved', 'dispatched')),
  provider TEXT,
  model TEXT,
  connection_id TEXT,
  pricing_snapshot TEXT
, usage_attributes TEXT NOT NULL DEFAULT '{}');
CREATE INDEX idx_usage_reservations_key
  ON api_key_usage_reservations(api_key_id);
